messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Animation Cycle</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #222; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x333333);

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(5, 3, 5);
        camera.lookAt(0, 1.5, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        const light = new THREE.DirectionalLight(0xffffff, 1);
        light.position.set(5, 10, 7.5);
        scene.add(light);
        scene.add(new THREE.AmbientLight(0x404040));

        // --- Treadmill Ground ---
        const groundGeo = new THREE.BoxGeometry(10, 0.2, 3);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        scene.add(ground);

        // --- Humanoid Figure ---
        const group = new THREE.Group();
        const mat = new THREE.MeshStandardMaterial({ color: 0x00ffcc });

        // Torso
        const torso = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.8, 0.4), mat);
        torso.position.y = 1.6;
        group.add(torso);

        // Head
        const head = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.3, 0.3), mat);
        head.position.y = 0.6;
        torso.add(head);

        // Limbs helper
        function createLimb(w, h, d) {
            const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
            mesh.position.y = -h / 2;
            return new THREE.Group(); // Pivot group
        }

        const leftLeg = new THREE.Group();
        const leftLegMesh = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.7, 0.2), mat);
        leftLegMesh.position.y = -0.35;
        leftLeg.add(leftLegMesh);
        leftLeg.position.set(-0.2, 1.2, 0);
        group.add(leftLeg);

        const rightLeg = new THREE.Group();
        const rightLegMesh = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.7, 0.2), mat);
        rightLegMesh.position.y = -0.35;
        rightLeg.add(rightLegMesh);
        rightLeg.position.set(0.2, 1.2, 0);
        group.add(rightLeg);

        const leftArm = new THREE.Group();
        const leftArmMesh = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.6, 0.15), mat);
        leftArmMesh.position.y = -0.3;
        leftArm.add(leftArmMesh);
        leftArm.position.set(-0.4, 2.0, 0);
        group.add(leftArm);

        const rightArm = new THREE.Group();
        const rightArmMesh = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.6, 0.15), mat);
        rightArmMesh.position.y = -0.3;
        rightArm.add(rightArmMesh);
        rightArm.position.set(0.4, 2.0, 0);
        group.add(rightArm);

        scene.add(group);

        // --- Animation Logic ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const t = clock.getElapsedTime();
            const cycleTime = t % 10; // 10 second loop

            let swingSpeed = 0;
            let swingAmplitude = 0;
            let lean = 0;
            let bounce = 0;

            if (cycleTime < 2) {
                // Stand still (0-2s)
                swingSpeed = 0;
                swingAmplitude = 0;
                lean = 0;
            } else if (cycleTime < 5) {
                // Walk (2-5s)
                swingSpeed = 4;
                swingAmplitude = 0.4;
                lean = 0.05;
                bounce = Math.sin(t * swingSpeed * 2) * 0.05;
            } else if (cycleTime < 8) {
                // Run (5-8s)
                swingSpeed = 8;
                swingAmplitude = 0.8;
                lean = 0.25;
                bounce = Math.sin(t * swingSpeed * 2) * 0.15;
            } else {
                // Stand still (8-10s)
                swingSpeed = 0;
                swingAmplitude = 0;
                lean = 0;
            }

            const phase = t * swingSpeed;

            // Rotate limbs
            leftLeg.rotation.x = Math.sin(phase) * swingAmplitude;
            rightLeg.rotation.x = -Math.sin(phase) * swingAmplitude;
            leftArm.rotation.x = -Math.sin(phase) * swingAmplitude;
            rightArm.rotation.x = Math.sin(phase) * swingAmplitude;

            // Apply torso lean and vertical bounce
            torso.rotation.x = lean;
            group.position.y = bounce;

            renderer.render(scene, camera);
        }

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
